/**
 * The Theatre of Blood, against the OSRS Wiki calculator's own code (tools/gen_tob.py): the hitpoints of every monster
 * of the raid for a party of 1 to 5 (tob.tsv), and whole sets of gear against the raid's bosses by the ids the game gives
 * them in combat (tob_sets.tsv): Sotetseg in normal and Hard Mode no longer reads the Entry Mode row.
 */
public class TobScalingTest
{
	@Test
	public void sameHitpointsAsTheCalculator() throws IOException
	{
		StyleData data = new StyleData();
		int rows = 0;
		List<String> off = new ArrayList<>();
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			TobScalingTest.class.getResourceAsStream("tob.tsv"), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				if (line.startsWith("#") || line.trim().isEmpty())
				{
					continue;
				}
				String[] c = line.split("\t", -1);
				StyleData.Monster m = data.monster(Integer.parseInt(c[0]));
				assertNotNull("the table has " + c[0], m);
				int got = TobScaling.hitpoints(m, m.hitpoints, new TobScaling.Raid(Integer.parseInt(c[2])));
				if (got != Integer.parseInt(c[4]))
				{
					off.add(c[0] + " " + c[1] + ", " + c[2] + " players: " + got + ", calculator " + c[4]);
				}
				rows++;
			}
		}
		assertTrue(off.size() + " off: " + off, off.isEmpty());
		assertTrue("the file has its cases", rows > 300);
	}

	@Test
	public void figuresAreTheCalculators() throws IOException
	{
		assertTrue(SetCalcTest.figuresOf("tob_sets.tsv").size() > 500);
	}

	/**
	 * On Xarpus and Verzik's second phase, in every mode, the Scythe of vitur attacks once every 16/3 ticks, not every 5
	 * (OSRS Wiki, Theatre of Blood/Strategies, Xarpus: "This uses 15/16 available ticks to damage the boss, or
	 * effectively a 5.33 tick attack speed"): each of its variants deals 15/16 of what it dealt there
	 * (the calculator's figure times 5 / (16/3) in tob_sets.tsv, tools/raid_cases.py), and the same as before everywhere
	 * else. Another 5-tick weapon is not touched.
	 */
	@Test
	public void theScytheIsSlowerOnXarpusAndVerziksSecondPhase() throws IOException
	{
		StyleData data = new StyleData();
		SetCalc.Player p = new SetCalc.Player();
		p.attack = 118;
		p.strength = 118;
		p.prayerAttack = 120;
		p.prayerStrength = 123;
		int[] walked = {10766, 10767, 10768, 10769, 8338, 8339, 8340, 8341, 10770, 10771, 10772, 10773,
			10833, 10834, 8372, 8373, 10850, 10851};
		for (String weapon : new String[]{"Scythe of vitur", "Holy scythe of vitur", "Sanguine scythe of vitur"})
		{
			SetCalc.Loadout l = scythe(data, weapon);
			for (int id : walked)
			{
				// the ids the table does not list find Xarpus by his name, as in game
				SetCalc.Target t = data.monster(id, id < 10833 && id != 8372 && id != 8373 ? "Xarpus" : "Verzik Vitur").target();
				assertEquals(id + "", 16.0 / 3, t.scytheSpeed, 0);
				double slower = SetCalc.perTick(l, p, t, false);
				t.scytheSpeed = 0;
				double before = SetCalc.perTick(l, p, t, false);
				assertTrue(weapon + " on " + id, before > 0);
				assertEquals(weapon + " on " + id, before * 15 / 16, slower, 1e-12);
			}
		}
		// Verzik's first and third phases, Sotetseg, the Maiden, the Nylocas Vasilias, a boss outside the raid: the
		// weapon's own speed (and every case of the calculator's files stays its figure: figuresAreTheCalculators)
		for (int id : new int[]{8369, 8370, 10830, 10847, 8374, 8375, 10835, 10852, 8388, 10868, 8360, 8355, 2215})
		{
			assertEquals(id + "", 0, data.monster(id).target().scytheSpeed, 0);
			assertEquals(id + "", 0, Weapons.scytheSpeed(id), 0);
		}
		// another weapon of 5 ticks keeps its speed on Xarpus
		SetCalc.Loadout axe = scythe(data, "Soulreaper axe");
		SetCalc.Target xarpus = data.monster(8340).target();
		double axeNow = SetCalc.perTick(axe, p, xarpus, false);
		xarpus.scytheSpeed = 0;
		assertEquals(SetCalc.perTick(axe, p, xarpus, false), axeNow, 0);
		assertTrue(axeNow > 0);
		// the calculator's case of the Scythe on Xarpus (tob_sets.tsv) is the plugin's, at 15/16 of the calculator's own
		int cases = 0;
		for (SetCalcTest.Case k : SetCalcTest.cases("tob_sets.tsv"))
		{
			if ("tob-scythe".equals(k.set) && Weapons.scytheSpeed(k.npc) > 0)
			{
				assertEquals(k.npc + "", k.expected, k.got, 0.001 * k.expected);
				cases++;
			}
		}
		assertTrue("cases", cases >= 18);
	}

	/**
	 * On every phase of Verzik, in every mode, any carried weapon is pointed at, as against a boss that does not change
	 * form: each phase is plain to see. The figures: on the second phase the Scythe in hand (Ultor ring, Torva full
	 * helm, Oathplate, Infernal max cape, Rancour, Ferocious, Avernic treads (max); Piety and a super combat) at 16/3
	 * ticks 9.19, against Tumeken's shadow with the whole magic switch (Ancestral, Imbued Zamorak max cape, Occult,
	 * Confliction, Magus ring, the same treads; Augury and a saturated heart, +13) 9.85, the magic defence rolled with
	 * Defence 200: the Shadow is pointed at with the Scythe in hand, nothing with the Shadow in hand. The third phase:
	 * each weapon at its own speed.
	 */
	@Test
	public void everyPhaseOfVerzikPointsAtAnyCarriedWeapon() throws IOException
	{
		assertFalse(CombatCheckPlugin.changesForm("Verzik Vitur"));
		StyleData data = new StyleData();
		SetCalc.Loadout scythe = meleeSet(data, 22325, "Scythe of vitur", "Scythe", 5, 120, 203, 80, 141);
		SetCalc.Loadout shadow = new SetCalc.Loadout();
		shadow.weaponName = "Tumeken's shadow";
		shadow.category = "Powered Staff";
		shadow.speed = 5;
		shadow.styles = data.styles(27275);
		shadow.stab = 5;
		shadow.slash = 5;
		shadow.crush = 5;
		shadow.magic = 177;
		shadow.ranged = -6;
		shadow.strength = 6;
		shadow.rangedStrength = 3;
		shadow.magicDamage = 27;
		SetCalc.Player magic = new SetCalc.Player();
		magic.magic = 112;
		magic.prayerMagic = 125;
		magic.prayerMagicDamage = 4;
		for (int id : new int[]{8372, 10850})
		{
			SetCalc.Target p2 = data.monster(id).target();
			double withScythe = SetCalc.perTick(scythe, meleePlayer(), p2, false);
			double withShadow = SetCalc.perTick(shadow, magic, p2, false);
			if (id == 8372)
			{
				// the file's figures are per second, a tick is 0.6 s
				assertEquals("the Scythe at 16/3 ticks", 9.19, withScythe / 0.6, 0.01);
				assertEquals("the Shadow", 9.85, withShadow / 0.6, 0.01);
			}
			// the Shadow is pointed at with the Scythe in hand (at least the default minimum gain, 1%), not the other way
			assertTrue(id + ": " + withShadow + " over " + withScythe, SetCalc.gain(withScythe, withShadow) >= 1);
			assertTrue(id + "", SetCalc.gain(withShadow, withScythe) < 1);
		}
		// the third phase: the weapon's own speed, no rule of the first phase
		for (int id : new int[]{10835, 8374, 10852})
		{
			assertFalse(id + "", data.monster(id).target().verzikP1);
			assertEquals(id + "", 0, data.monster(id).target().scytheSpeed, 0);
		}
	}

	/**
	 * Verzik's first phase, as it is played: two attacks of any 4 or 5-tick weapon between two of her magic attacks, 14
	 * ticks apart (OSRS Wiki, Theatre of Blood/Strategies, Verzik Vitur - phase 1: "which allows for two hits by any 4 or
	 * 5-tick weapon"), so weapons are compared by what one attack deals, each hit held at 10 by her shield. The Abyssal
	 * tentacle (4 ticks) deals more per tick than the Noxious halberd (5 ticks) at their own speeds, and a little less per
	 * attack (the calculator: 4.51 and 4.57): with the halberd in hand the tentacle is not
	 * pointed at. The Scythe, 12.04 an attack. The Dawnbringer has no figure: never pointed at, nothing pointed at while
	 * it is in hand. Ranged, magic and other speeds have no figure there.
	 */
	@Test
	public void verziksFirstPhaseComparesWhatOneAttackDeals() throws IOException
	{
		StyleData data = new StyleData();
		SetCalc.Loadout tentacle = meleeSet(data, 12006, "Abyssal tentacle", "Whip", 4, 80, 197, 78, 160);
		SetCalc.Loadout halberd = meleeSet(data, 29796, "Noxious halberd", "Polearm", 5, 130, 210, 50, 208);
		SetCalc.Loadout scythe = meleeSet(data, 22325, "Scythe of vitur", "Scythe", 5, 120, 203, 80, 141);
		for (int id : new int[]{8370, 10831, 10848})
		{
			SetCalc.Target p1 = data.monster(id).target();
			assertTrue(id + "", p1.verzikP1);
			double tentacleTick = SetCalc.perTick(tentacle, meleePlayer(), p1, false);
			double halberdTick = SetCalc.perTick(halberd, meleePlayer(), p1, false);
			// at their own speeds the tentacle would be pointed at (about 23% more), per attack it is not
			assertTrue(id + "", SetCalc.gain(halberdTick, tentacleTick) > 20);
			double tentacleRate = CombatCheckPlugin.verzikP1Rate(tentacleTick, StyleCalc.MELEE, 4);
			double halberdRate = CombatCheckPlugin.verzikP1Rate(halberdTick, StyleCalc.MELEE, 5);
			assertTrue(id + ": " + halberdRate + " " + tentacleRate, SetCalc.gain(halberdRate, tentacleRate) < 1);
			assertTrue(id + "", SetCalc.gain(tentacleRate, halberdRate) >= 1);
		}
		SetCalc.Target normal = data.monster(8370).target();
		assertEquals(4.51, SetCalc.perTick(tentacle, meleePlayer(), normal, false) * 4, 0.02);
		assertEquals(4.57, SetCalc.perTick(halberd, meleePlayer(), normal, false) * 5, 0.02);
		double scytheTick = SetCalc.perTick(scythe, meleePlayer(), normal, false);
		assertEquals(12.04, scytheTick * 5, 0.02);
		// two attacks in each 14 ticks
		assertEquals(12.04 * 2 / 14, CombatCheckPlugin.verzikP1Rate(scytheTick, StyleCalc.MELEE, 5), 0.002);
		// no figure for what the wiki gives no rhythm for
		assertEquals(-1, CombatCheckPlugin.verzikP1Rate(1, StyleCalc.RANGED, 4), 0);
		assertEquals(-1, CombatCheckPlugin.verzikP1Rate(1, StyleCalc.MAGIC, 5), 0);
		assertEquals(-1, CombatCheckPlugin.verzikP1Rate(1, StyleCalc.MELEE, 6), 0);
		assertEquals(-1, CombatCheckPlugin.verzikP1Rate(-1, StyleCalc.MELEE, 5), 0);
		// the Dawnbringer: no figure, so never pointed at and nothing pointed at while it is in hand
		SetCalc.Loadout dawnbringer = new SetCalc.Loadout();
		dawnbringer.weaponName = "Dawnbringer";
		dawnbringer.category = "Staff";
		dawnbringer.speed = 4;
		assertFalse(SetCalc.plain(dawnbringer));
	}

